mapper.select:
SELECT s.salary_id, s.emp_id, e.ename AS employee_name, s.salary_year_month, s.base_salary, s.bonus, s.deduction, s.net_salary, s.payment_date FROM salary s LEFT JOIN emp e ON e.emp_id = s.emp_id
AND s.salary_year_month = #{salaryYearMonth}
AND (LOCATE(#{employeeKeyword}, e.ename) > 0
OR s.emp_id = #{employeeId}
)
ORDER BY s.salary_year_month DESC, s.salary_id DESC

SELECT COUNT(*)
FROM emp
WHERE emp_id = #{empId}

SELECT COUNT(*)
FROM salary
WHERE emp_id = #{empId}
  AND salary_year_month = #{salaryYearMonth}
